const fs = require("fs");
const path = require("path");
const assert = require("assert");
const JSDOM = require("jsdom").JSDOM;

const html = fs.readFileSync(path.resolve("app/index.html"), "utf8");
const dom = new JSDOM(html);
const window = dom.window;
global.window = window;
global.document = window.document;

window.eval(fs.readFileSync(path.resolve("app/js/player.js"), "utf8"));
const { PlayerController } = window;
PlayerController.init();

console.log("=== ADVERSARIAL STRESS TEST: 5-Stage Teardown & Idempotency ===");

const video = window.document.getElementById("main-video-player");
let loadCalls = 0;
let pauseCalls = 0;
video.load = () => { loadCalls++; };
video.pause = () => { pauseCalls++; };
video.setAttribute("src", "http://test/stream.m3u8");

// Add dummy track
const track = window.document.createElement("track");
video.appendChild(track);
assert.strictEqual(video.children.length, 1);

// Set fake HLS
let hlsDestroyed = false;
PlayerController.hls = {
  stopLoad: () => {},
  detachMedia: () => {},
  destroy: () => { hlsDestroyed = true; }
};

// Call destroy 1st time
PlayerController.destroy();

assert.strictEqual(hlsDestroyed, true, "HLS must be destroyed");
assert.strictEqual(PlayerController.hls, null, "HLS reference cleared");
assert.strictEqual(video.hasAttribute("src"), false, "src attribute removed");
assert.strictEqual(video.children.length, 0, "All tracks purged");
assert.strictEqual(loadCalls, 1, "video.load() called to reclaim VDEC");
assert.strictEqual(PlayerController.state, "IDLE", "State reset to IDLE");

// Call destroy 2nd and 3rd time (idempotency check)
PlayerController.destroy();
PlayerController.destroy();

assert.strictEqual(PlayerController.state, "IDLE");
console.log("PASS: 5-Stage Teardown & Idempotency verified without errors!");
