console.log("=== ADVERSARIAL STRESS TEST: Multi-Server Fallback Cascade ===");

let attemptedServers = [];
PlayerController._fetchStreamResolution = (item, serverName) => {
  attemptedServers.push(serverName);
  if (serverName === "secret") {
    return Promise.reject(new Error("Secret server 500 error"));
  }
  if (serverName === "Nebula") {
    return Promise.reject(new Error("Nebula timeout"));
  }
  // Lisbon succeeds!
  return Promise.resolve({
    streamUrl: "http://127.0.0.1:8088/hls/proxy?url=lisbon.m3u8",
    originalUrl: "https://lightspeed.st/hls/lisbon.m3u8",
    server: "Lisbon",
    subtitles: []
  });
};

PlayerController._resolveStreamWithFallback({ tmdbId: 12345, type: "movie" }, "secret", 0)
  .then((res) => {
    console.log("Resolved result:", res.server, "after attempts:", attemptedServers);
    assert.deepStrictEqual(attemptedServers, ["secret", "Nebula", "Lisbon"]);
    assert.strictEqual(res.server, "Lisbon");
    console.log("PASS: Multi-server cascade resolved correctly!");
  })
  .catch((err) => {
    console.error("FAIL:", err);
    process.exit(1);
  });
